const double INCH_TO_METER = 0.0254;

pros::Controller controller(pros::E_CONTROLLER_MASTER);

pros::MotorGroup rightMotors({11, 12, 13});
pros::MotorGroup leftMotors({-18, -19, -20});

// FIX: Convert track width and wheel diameter to meters
lemlib::Drivetrain drivetrain(&leftMotors, &rightMotors,
                              10.05, // 10 inches -> meters
                              4,     // LemLib handles this enum, but it's 4 inches
                              160, 2);

pros::IMU imu(15);

pros::Rotation horizontal_tracking_sensor(6);
pros::Rotation vertical_tracking_sensor(-16);

lemlib::TrackingWheel horizontal_tracking_wheel(&horizontal_tracking_sensor,
                                                2,   // 2 inch wheel diameter -> meters
                                                7.1, // 7.1 inch offset -> meters
                                                1);
lemlib::TrackingWheel vertical_tracking_wheel(&vertical_tracking_sensor,
                                              2,   // 2 inch wheel diameter -> meters
                                              0.1, // 0.1 inch offset -> meters
                                              1);

lemlib::OdomSensors sensors(&vertical_tracking_wheel, nullptr, &horizontal_tracking_wheel, nullptr, &imu);

// FIX: Convert lateral controller error ranges to meters
lemlib::ControllerSettings lateral_controller(10, // kP
                                              0,  // kI
                                              3,  // kD
                                              3,  // windup
                                              1,  // small error range in meters
                                              100,
                                              3, // large error range in meters
                                              500,
                                              20 // slew rate in meters/sec^2
);

// Angular controller error ranges are in degrees, so they don't need conversion
lemlib::ControllerSettings angular_controller(4,    // kP
                                              0.01, // kI
                                              20,   // kD
                                              3,    // windup
                                              1,    // small error range in degrees
                                              100,
                                              3, // large error range in degrees
                                              500, 0);

lemlib::Chassis chassis(drivetrain, lateral_controller, angular_controller, sensors);

pros::Distance right(3);
pros::Distance left(4);
pros::Distance back(2);
pros::Distance front(17);

ASSET(skills_1_txt);

class Vector2 {
public:
    Vector2(float x, float y) : x(x), y(y) {}
    std::string latex() const {
        std::ostringstream oss;
        oss << "\\left(" << std::fixed << this->x << "," << std::fixed << this->y << "\\right)";
        return oss.str();
    }

    float x;
    float y;
};

double sign(double x) {
    if (x > 0)
        return 1;
    else if (x < 0)
        return -1;
    else
        return 0;
}

struct VelocityProfile {
    double KV = 0.0536081766093, KA = 0.00318573203587, KS = 0.355059053395;
};

struct State {
    double x, y, heading, linear_vel, angular_vel;
};


/**
 * @brief Minimum confidence level from a sensor to be considered valid.
 * (Range: 0-100)
 */
const double MIN_CONFIDENCE = 20;

/**
 * @brief Minimum object size (in mm) for a sensor to consider it a wall.
 * (VEX V5 sensor specific)
 */
const double MIN_WALL_OBJECT_SIZE = 5;

/**
 * @brief How "perpendicular" a sensor must be to a wall to be trusted.
 * 1.0 = perfectly perpendicular (90 deg to wall).
 * 0.866 = within 30 degrees.
 * 0.707 = within 45 degrees.
 * LOWER: Trusts sensors at sharper angles, but may be less accurate.
 * HIGHER: Requires a more direct "look" at the wall, relies on odom more.
 */
const double MIN_PERPENDICULARITY = 0; // within 45 degrees

/**
 * @brief The maximum allowed difference (in inches) between sensor readings
 * for the same axis. If the disparity is larger, the readings are
 * considered conflicting, and odometry will be used instead.
 * LOWER: Trusts sensors less, relies on odometry more.
 */
const double MAX_CANDIDATE_DISPARITY = 16; // 10 inches

// --- Field & Sensor Constants ---
const double MM_TO_IN = 0.0393701;
const double FIELD_WIDTH = 3657.6 * MM_TO_IN;  // 144 inches
const double FIELD_HEIGHT = 3657.6 * MM_TO_IN; // 144 inches
const double HALF_WIDTH = FIELD_WIDTH / 2.0;   // 72 inches
const double HALF_HEIGHT = FIELD_HEIGHT / 2.0; // 72 inches
const double MAX_SENSOR_RANGE = 1800 * MM_TO_IN; // ~78.7 inches
const double MIN_SENSOR_RANGE = 50 * MM_TO_IN;   // ~2 inches


struct SensorConfig {
    double forward_offset; // inches
    double strafe_offset;  // inches
    double mounting_angle; // degrees
};

// Sensor positions relative to robot center (forward_offset = +Y, strafe_offset = +X)
const SensorConfig front_sensor_cfg = {9, 0.25, 0};   // 9" fwd, 0.25" left, points 0 deg (fwd)
const SensorConfig left_sensor_cfg  = {-1.25, -5.5, 90};    // 5" fwd, 0" strafe, points 90 deg (left)
const SensorConfig right_sensor_cfg = {-1.25, 5.5, -90};   // 5" fwd, 4" right, points -90 deg (right)
const SensorConfig back_sensor_cfg  = {-7.75, -0.25, 180}; // 8" back, 0.25" right, points 180 deg (back)


/**
 * @brief Holds all data from a single distance sensor reading.
 */
struct SensorReadings {
    double dist_mm;
    int object_size;
    int confidence;
};

/**
 * @brief Return struct for the global position calculation.
 */
struct distancePose {
    double x;            // Estimated global X
    double y;            // Estimated global Y
    bool using_odom_x;   // True if X is from odometry (no sensor lock)
    bool using_odom_y;   // True if Y from odometry (no sensor lock)
};



distancePose calculateGlobalPosition(
    const SensorReadings& front_data,
    const SensorReadings& left_data,
    const SensorReadings& right_data,
    const SensorReadings& back_data,
    double heading_deg)
{
    lemlib::Pose current_pose = chassis.getPose();
    double est_x = current_pose.x;
    double est_y = current_pose.y;

    bool using_odom_x = true;
    bool using_odom_y = true;

    // (SensorData array and is_valid helper are unchanged)
    struct SensorData { SensorConfig cfg; double dist_in; };
    const SensorData sensors[] = {
        {front_sensor_cfg, front_data.dist_mm * MM_TO_IN},
        {left_sensor_cfg,  left_data.dist_mm * MM_TO_IN},
        {right_sensor_cfg, right_data.dist_mm * MM_TO_IN},
        {back_sensor_cfg,  back_data.dist_mm * MM_TO_IN}
    };
    auto is_valid = [&](int i) {
        return (sensors[i].dist_in < MAX_SENSOR_RANGE && 
                sensors[i].dist_in >= MIN_SENSOR_RANGE);
    };

    // (Heading normalization and TOLERANCE are unchanged)
    double norm_heading = std::fmod(heading_deg, 360.0);
    if (norm_heading < 0) norm_heading += 360.0;
    const double TOLERANCE = 40.0; 
    
    std::vector<double> x_cands;
    std::vector<double> y_cands;

    // --- THIS IS THE FIX ---
    // Helper lambda to calculate the global offset of a sensor
    // This math is for a CLOCKWISE system (0 = +Y, 90 = +X)
    // which matches the logic in your if/else blocks.
    auto get_global_offsets = [&](const SensorConfig& cfg, double heading_rad) {
        double cos_h = std::cos(heading_rad);
        double sin_h = std::sin(heading_rad);
        
        // [FIXED] This is the correct rotation math for your 0 = +Y system
        double global_offset_x = (cfg.forward_offset * sin_h) + (cfg.strafe_offset * cos_h);
        double global_offset_y = (cfg.forward_offset * cos_h) - (cfg.strafe_offset * sin_h);
        
        return std::make_pair(global_offset_x, global_offset_y);
    };
    // --- END OF FIX ---


    // (Case 1: Facing UP - unchanged)
    if (norm_heading <= TOLERANCE || norm_heading >= 360.0 - TOLERANCE) {
        double angle_off_rad = (norm_heading <= TOLERANCE) ? 
            lemlib::degToRad(norm_heading) : lemlib::degToRad(norm_heading - 360.0);
        double heading_rad = angle_off_rad;

        double perp_dist_0 = sensors[0].dist_in * std::cos(angle_off_rad);
        double perp_dist_3 = sensors[3].dist_in * std::cos(angle_off_rad);
        double perp_dist_1 = sensors[1].dist_in * std::cos(angle_off_rad);
        double perp_dist_2 = sensors[2].dist_in * std::cos(angle_off_rad);

        auto offset_0 = get_global_offsets(sensors[0].cfg, heading_rad);
        auto offset_1 = get_global_offsets(sensors[1].cfg, heading_rad);
        auto offset_2 = get_global_offsets(sensors[2].cfg, heading_rad);
        auto offset_3 = get_global_offsets(sensors[3].cfg, heading_rad);

        if (is_valid(0)) { y_cands.push_back(HALF_HEIGHT - perp_dist_0 - offset_0.second); }
        if (is_valid(3)) { y_cands.push_back(-HALF_HEIGHT + perp_dist_3 - offset_3.second); }
        if (is_valid(1)) { x_cands.push_back(-HALF_WIDTH + perp_dist_1 - offset_1.first); }
        if (is_valid(2)) { x_cands.push_back(HALF_WIDTH - perp_dist_2 - offset_2.first); }
    }
    // (Case 2: Facing DOWN - unchanged)
    else if (std::fabs(norm_heading - 180.0) <= TOLERANCE) {
        double angle_off_rad = lemlib::degToRad(norm_heading - 180.0);
        double heading_rad = lemlib::degToRad(norm_heading);

        double perp_dist_0 = sensors[0].dist_in * std::cos(angle_off_rad);
        double perp_dist_3 = sensors[3].dist_in * std::cos(angle_off_rad);
        double perp_dist_1 = sensors[1].dist_in * std::cos(angle_off_rad);
        double perp_dist_2 = sensors[2].dist_in * std::cos(angle_off_rad);

        auto offset_0 = get_global_offsets(sensors[0].cfg, heading_rad);
        auto offset_1 = get_global_offsets(sensors[1].cfg, heading_rad);
        auto offset_2 = get_global_offsets(sensors[2].cfg, heading_rad);
        auto offset_3 = get_global_offsets(sensors[3].cfg, heading_rad);

        if (is_valid(0)) { y_cands.push_back(-HALF_HEIGHT + perp_dist_0 - offset_0.second); }
        if (is_valid(3)) { y_cands.push_back(HALF_HEIGHT - perp_dist_3 - offset_3.second); }
        if (is_valid(1)) { x_cands.push_back(HALF_WIDTH - perp_dist_1 - offset_1.first); }
        if (is_valid(2)) { x_cands.push_back(-HALF_WIDTH + perp_dist_2 - offset_2.first); }
    }
    // (Case 3: Facing RIGHT - unchanged)
    else if (std::fabs(norm_heading - 90.0) <= TOLERANCE) {
        double angle_off_rad = lemlib::degToRad(norm_heading - 90.0);
        double heading_rad = lemlib::degToRad(norm_heading);
        
        double perp_dist_0 = sensors[0].dist_in * std::cos(angle_off_rad);
        double perp_dist_3 = sensors[3].dist_in * std::cos(angle_off_rad);
        double perp_dist_1 = sensors[1].dist_in * std::cos(angle_off_rad);
        double perp_dist_2 = sensors[2].dist_in * std::cos(angle_off_rad);

        auto offset_0 = get_global_offsets(sensors[0].cfg, heading_rad);
        auto offset_1 = get_global_offsets(sensors[1].cfg, heading_rad);
        auto offset_2 = get_global_offsets(sensors[2].cfg, heading_rad);
        auto offset_3 = get_global_offsets(sensors[3].cfg, heading_rad);

        if (is_valid(0)) { x_cands.push_back(HALF_WIDTH - perp_dist_0 - offset_0.first); }
        if (is_valid(3)) { x_cands.push_back(-HALF_WIDTH + perp_dist_3 - offset_3.first); }
        if (is_valid(1)) { y_cands.push_back(HALF_HEIGHT - perp_dist_1 - offset_1.second); }
        if (is_valid(2)) { y_cands.push_back(-HALF_HEIGHT + perp_dist_2 - offset_2.second); }
    }
    // (Case 4: Facing LEFT - unchanged)
    else if (std::fabs(norm_heading - 270.0) <= TOLERANCE) {
        double angle_off_rad = lemlib::degToRad(norm_heading - 270.0);
        double heading_rad = lemlib::degToRad(norm_heading);

        double perp_dist_0 = sensors[0].dist_in * std::cos(angle_off_rad);
        double perp_dist_3 = sensors[3].dist_in * std::cos(angle_off_rad);
        double perp_dist_1 = sensors[1].dist_in * std::cos(angle_off_rad);
        double perp_dist_2 = sensors[2].dist_in * std::cos(angle_off_rad);
        
        auto offset_0 = get_global_offsets(sensors[0].cfg, heading_rad);
        auto offset_1 = get_global_offsets(sensors[1].cfg, heading_rad);
        auto offset_2 = get_global_offsets(sensors[2].cfg, heading_rad);
        auto offset_3 = get_global_offsets(sensors[3].cfg, heading_rad);
        
        if (is_valid(0)) { x_cands.push_back(-HALF_WIDTH + perp_dist_0 - offset_0.first); }
        if (is_valid(3)) { x_cands.push_back(HALF_WIDTH - perp_dist_3 - offset_3.first); }
        if (is_valid(1)) { y_cands.push_back(-HALF_HEIGHT + perp_dist_1 - offset_1.second); }
        if (is_valid(2)) { y_cands.push_back(HALF_HEIGHT - perp_dist_2 - offset_2.second); }
    }

    // --- 4. Average the results (unchanged) ---
    if (!x_cands.empty()) {
        est_x = std::accumulate(x_cands.begin(), x_cands.end(), 0.0) / x_cands.size();
        using_odom_x = false;
    }

    if (!y_cands.empty()) {
        est_y = std::accumulate(y_cands.begin(), y_cands.end(), 0.0) / y_cands.size();
        using_odom_y = false;
    }

    // --- 5. Return Final Pose (unchanged) ---
    distancePose pose;
    pose.x = est_x;
    pose.y = est_y;
    pose.using_odom_x = using_odom_x;
    pose.using_odom_y = using_odom_y;
    return pose;
}




distancePose distanceReset() {
    // Assumes you can get the IMU heading directly from the chassis or an IMU object
    double heading_deg = chassis.getPose().theta; // Or imu.get_rotation(), etc.

    // Create SensorReadings structs
    SensorReadings front_data = {(double)front.get_distance(), front.get_object_size(), front.get_confidence()};
    SensorReadings left_data  = {(double)left.get_distance(),  left.get_object_size(),  left.get_confidence()};
    SensorReadings right_data = {(double)right.get_distance(), right.get_object_size(), right.get_confidence()};
    SensorReadings back_data  = {(double)back.get_distance(),  back.get_object_size(),  back.get_confidence()};

    return calculateGlobalPosition(front_data, left_data, right_data, back_data, heading_deg);
}

/**
 * @brief Helper function to calculate position using only specified sensors.
 */
distancePose distanceReset(bool left_use, bool right_use, bool front_use, bool back_use) {
    double heading_deg = chassis.getPose().theta; // Or imu.get_rotation(), etc.

    // This distance (in mm) is larger than MAX_SENSOR_RANGE, so it will be ignored
    const int invalid_dist_mm = 10000; 
    const int invalid_confidence = 0; // This will fail the MIN_CONFIDENCE check

    SensorReadings front_data = front_use
        ? SensorReadings{front.get_distance() * MM_TO_IN, front.get_object_size(), front.get_confidence()}
        : SensorReadings{invalid_dist_mm, 0, invalid_confidence};
    
    SensorReadings left_data = left_use
        ? SensorReadings{left.get_distance() * MM_TO_IN, left.get_object_size(), left.get_confidence()}
        : SensorReadings{invalid_dist_mm, 0, invalid_confidence};

    SensorReadings right_data = right_use
        ? SensorReadings{right.get_distance() * MM_TO_IN, right.get_object_size(), right.get_confidence()}
        : SensorReadings{invalid_dist_mm, 0, invalid_confidence};

    SensorReadings back_data = back_use
        ? SensorReadings{back.get_distance() * MM_TO_IN, back.get_object_size(), back.get_confidence()}
        : SensorReadings{invalid_dist_mm, 0, invalid_confidence};


    return calculateGlobalPosition(front_data, left_data, right_data, back_data, heading_deg);
}




std::vector<State> prepare_trajectory() {
    std::vector<State> states;
    states.resize(X.size());

    for (int i = 0; i < X.size(); i++) {
        states[i].x = X.at(i).first;
        states[i].y = X.at(i).second;
        states[i].linear_vel = L.at(i).second;
        states[i].angular_vel = A.at(i).second;
    }

    for (int i = 0; i < states.size() - 1; i++) {
        states[i].heading = atan2(states[i + 1].y - states[i].y, states[i + 1].x - states[i].x);
    }

    if (!states.empty()) {
        states.back().heading = states[states.size() - 2].heading;
    }

    return states;
}

class VelocityController {
public:
    // Gains
    double kV; // velocity feedforward
    double kA; // acceleration feedforward
    double kS; // static friction compensation
    double kP; // proportional gain
    double kI; // integral gain

    VelocityController(double kv, double ka, double ks, double kp, double ki)
        : kV(kv), kA(ka), kS(ks), kP(kp), kI(ki), integral(0.0), lastTargetVelocity(0.0), pid(kp, ki, 0, 0, false) {}

    double update(double targetVelocity, double measuredVelocity) {
        // Velocity error
        double error = targetVelocity - measuredVelocity;
        // Change in target velocity (acceleration)
        double deltaTargetVelocity = (targetVelocity - lastTargetVelocity) / 0.01;
        // Static compensation
        double staticTerm = kS * sign(targetVelocity);
        double integralTerm = integral + error * 0.01;

        // Total output voltage
        double voltage = kV * targetVelocity + kA * deltaTargetVelocity + staticTerm + kP * error + kI * integralTerm;

        lastTargetVelocity = targetVelocity;
        integral = integralTerm;
        return std::max(-12.0, std::min(12.0, voltage));
    }

private:
    double integral;
    double lastTargetVelocity;
    lemlib::PID pid;

    int sign(double x) {
        return (x > 0) - (x < 0); // returns 1, 0, or -1
    }
};

struct VelocityControllerConfig {
    double kV = 0.0; // velocity feedforward
    double kA = 0.0; // acceleration feedforward
    double kS = 0.0; // static friction compensation
    double kP = 0.0; // proportional gain
    double kI = 0.0; // integral gain

    VelocityControllerConfig() = default;

    VelocityControllerConfig(double kv, double ka, double ks, double kp, double ki)
        : kV(kv), kA(ka), kS(ks), kP(kp), kI(ki) {}
};

// Wrap angle difference into range [-pi, pi)
double angleError(double robotAngle, double targetAngle) {
    constexpr double TWO_PI = 2.0 * M_PI;

    double diff = std::fmod(targetAngle - robotAngle, TWO_PI);

    if (diff < -M_PI) {
        diff += TWO_PI;
    } else if (diff >= M_PI) {
        diff -= TWO_PI;
    }

    return diff;
}


const double wheel_circumference = 4 * M_PI * INCH_TO_METER; // meters
const double gear_ratio = 0.8;
const double rps_to_mps_factor = (wheel_circumference / gear_ratio) / 60;
VelocityControllerConfig config{0.0536081766093, 0.00318573203587, 0.355059053395, 0.109602958174, 1.98706406926};

inline double sinc(double x) {
    const double eps = 1e-9;
    if (std::abs(x) < eps) {
        // 1 - x^2/6 + O(x^4)
        return 1.0 - (x * x) / 6.0;
    }
    return std::sin(x) / x;
}

void ramsete_auton() {
    const double b = 0.1;      // Controls how strongly/Aggresiveley the controller follows the path
    const double zeta = 0.5; // Basically a damping term
    const double track_width = 10.05 * INCH_TO_METER;
    VelocityProfile vp;

    VelocityController right_controller(config.kV, config.kA, config.kS, config.kP, config.kI);
    VelocityController left_controller(config.kV, config.kA, config.kS, config.kP, config.kI);

    std::vector<State> trajectory = prepare_trajectory();
    if (trajectory.empty())
        return;

    chassis.setPose(trajectory[0].x / INCH_TO_METER, trajectory[0].y / INCH_TO_METER, chassis.getPose(true).theta, true);
    std::vector<std::string> logs;
    float time = 0;
    for (const auto &target_state : trajectory) {

        lemlib::Pose current_pose = chassis.getPose(true);
        Eigen::Matrix3d rotation_matrix;
        Eigen::Vector3d global_error;
        Eigen::Vector3d local_error;

        current_pose.x *= INCH_TO_METER;
        current_pose.y *= INCH_TO_METER;
        current_pose.theta = M_PI_2 - current_pose.theta;
        double AngleError = angleError(current_pose.theta, target_state.heading); 

        rotation_matrix << std::cos(current_pose.theta), std::sin(current_pose.theta), 0, -std::sin(current_pose.theta),
            std::cos(current_pose.theta), 0, 0, 0, 1;

        global_error << target_state.x - current_pose.x, target_state.y - current_pose.y,
            AngleError;

        local_error = rotation_matrix * global_error;

        double vd = target_state.linear_vel;
        double wd = target_state.angular_vel;
        double e_x = local_error(0);
        double e_y = local_error(1);
        double e_t = local_error(2);

        double k = 2.0 * zeta * std::sqrt(wd * wd + b * vd * vd);
        double v = vd * std::cos(e_t) + k * e_x;
        double w = wd + k * e_t + (b * vd * sinc(e_t) * e_y);

        //std::cout << Vector2(time, local_error.norm()).latex() << ",";
        //std::cout.flush();

        double left_target_velocity = (60 * 1.25 / wheel_circumference) * (v- (track_width / 2.0) * w);
        double right_target_velocity = (60 * 1.25 / wheel_circumference) * (v + (track_width / 2.0) * w);
        double left = left_controller.update(left_target_velocity, leftMotors.get_actual_velocity());
        double right = right_controller.update(right_target_velocity, rightMotors.get_actual_velocity());

        rightMotors.move_voltage(right * 1000.0);
        leftMotors.move_voltage(left * 1000.0);

        //rightMotors.move_velocity(right_target_velocity);
        //leftMotors.move_velocity(left_target_velocity);
        
        std::ostringstream ss;
        ss << Vector2(time, rightMotors.get_actual_velocity()).latex() << ",";
        /*
        std::ostringstream s2;
        s2 << Vector2(time, e_y).latex() << ",";
        std::ostringstream s3;
        s3 << Vector2(time, e_t).latex() << ",";
        */
        //std::ostringstream s5;
        //s5 << Vector2(current_pose.x, current_pose.y).latex() << ",";
        
        //std::ostringstream s4;
        //s4 << Vector2(time, right_target_velocity).latex() << ",";
        /*<< "time=" << time
           << " e_x=" << e_x
           << " e_y=" << e_y
           << " e_t=" << e_t
           << " vd=" << vd
           << " wd=" << wd
           << " v=" << v
           << " w=" << w
           << " left_target_velocity=" << left_target_velocity
           << " right_target_velocity=" << right_target_velocity
           << " current_pose.x=" << current_pose.x
           << " current_pose.y=" << current_pose.y
           << " current_pose.theta=" << current_pose.theta;*/

        
        logs.push_back(ss.str());
        /*
        logs.push_back(s2.str());
        logs.push_back(s3.str());
        */
        //logs.push_back(s4.str());
        //logs.push_back(s5.str());

        // 
        //std::cout.flush();
        //std::cout << Vector2(current_pose.x, current_pose.y).latex() << ",";
        //std::cout << Vector2(current_pose.x, current_pose.y).latex() << ",";
        //  std::cout << Vector2(pros::millis()/1000,left_target_velocity).latex() << ",";
        //std::cout.flush();
        

        pros::delay(10);
        time += 0.01;
    }

    rightMotors.brake();
    leftMotors.brake();

    for (const auto& line : logs) {
        std::cout << line;
        pros::delay(100);
    }
}

void test_w_controller() {
    double right = 0;
    double left = 0;
    double time = pros::millis();
    VelocityController right_controller(config.kV, config.kA, config.kS, config.kP, config.kI);
    VelocityController left_controller(config.kV, config.kA, config.kS, config.kP, config.kI);
    while(true) {
        if (pros::millis() - time <= 2000) {
            left = left_controller.update(200, leftMotors.get_actual_velocity());
            right = right_controller.update(-200, rightMotors.get_actual_velocity());
        }
        else {
            left = left_controller.update(-200, leftMotors.get_actual_velocity());
            right = right_controller.update(200, rightMotors.get_actual_velocity());
        }

        rightMotors.move_voltage(right * 1000.0);
        leftMotors.move_voltage(left * 1000.0);
        pros::delay(10);
        std::cout << Vector2(pros::millis() - time, leftMotors.get_actual_velocity()).latex() << ",";
    }
}

